import random
def hold_win_bonus(initial_coins, base_bet):
    grid = init_locked_grid(initial_coins)
    respins = 3
    while respins > 0 and not grid_full(grid):
        result = spin_open_positions(grid)
        new_coins = [c for c in result if c.is_coin]
        if new_coins:
            for c in new_coins:
                c.value = roll_coin_value()
                grid.add_coin(c)
            respins = 3
        else:
            respins -= 1
    if grid_full(grid):
        emit_animation_event('grid_full_jackpot', 2000)
        return 2000 * base_bet
    return sum(c.value for c in grid.coins) * base_bet

def roll_coin_value():
    types = ['credit_2x','credit_5x','MINI','MINOR','MAJOR','GRAND']
    weights = [0.65, 0.22, 0.098, 0.02, 0.005, 0.0001]
    weights = [w/sum(weights) for w in weights]
    return random.choices(types, weights=weights, k=1)[0]

from collections import namedtuple
Card = namedtuple('Card', ['rank','suit','color'])
def resolve_perfect_pairs(player_two_cards, side_bet_units):
    c1, c2 = player_two_cards
    if c1.rank != c2.rank:
        return -side_bet_units
    if c1.suit == c2.suit:
        return 25 * side_bet_units
    if c1.color == c2.color:
        return 12 * side_bet_units
    return 6 * side_bet_units

