import random
REEL_SYMBOLS = ['cherry','lemon','orange','grape','bell','star','jackpot','diamond','wild','scatter','expanding_wild','multiplier_wild']
REEL_WEIGHTS = [12,10,9,8,6,5,3,2,2,2,0.7,0.3]

def spin_one_reel():
    return [random.choices(REEL_SYMBOLS, weights=REEL_WEIGHTS, k=1)[0] for _ in range(3)]

def spin_5x3():
    grid = [spin_one_reel() for _ in range(5)]
    # emit per-reel animations with stagger
    for reel_idx, column in enumerate(grid):
        emit_animation_event('A1_REEL_SPIN', {'reel_idx': reel_idx, 'symbols': column, 'stagger_ms': reel_idx * 80})
    # detect scatters
    scatter_count = sum(1 for col in grid for s in col if s == 'scatter')
    if scatter_count >= 3:
        emit_animation_event('A8_FREE_SPINS_TRIGGER', {'count': scatter_count})
        spawn_free_spins(scatter_count)
    # detect expanding wild
    for reel_idx, column in enumerate(grid):
        if 'expanding_wild' in column:
            emit_animation_event('expanding_wild_grow', {'reel_idx': reel_idx})
            grid[reel_idx] = ['wild','wild','wild']
    # compute payline wins
    wins = compute_payline_wins(grid)
    if wins['total'] > 0:
        if wins['total'] >= 50 * BET:
            emit_animation_event('A5_BIG_WIN', {'amount': wins['total']})
        else:
            emit_animation_event('A2_COIN_CASCADE', {'amount': wins['total']})
    return wins

